def rotate_items(items, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k < 0:
        raise ValueError("k must be nonnegative")

    items = tuple(items)
    if not items:
        return None

    k %= len(items)
    return items[-k:] + items[:-k] if k else items

def interleave(left, right):
    if len(left) != len(right):
        raise ValueError("left and right must be equally sized")
    return tuple(item for pair in zip(left, right) for item in pair)

def sort_labels(labels):
    labels = tuple(labels)
    if not labels:
        return None

    first_spelling = {}
    for label in labels:
        first_spelling.setdefault(label.casefold(), label)

    return tuple(first_spelling[key] for key in sorted(first_spelling))

def find_products(products, query):
    if not products:
        return None
    matches = [product for product in products if query in product["name"]]
    return tuple(sorted(matches, key=lambda product: product["score"], reverse=True))

def group_words(words):
    if not words:
        return None

    groups = {}
    for word in words:
        initial = word[0]
        groups.setdefault(initial, []).append(word)

    return tuple((initial, tuple(group)) for initial, group in groups.items())

def parse_integer_fields(fields):
    values = tuple(int(field) for field in fields)
    return values if values else None

from datetime import date

def nearest_date(dates, target):
    if not dates:
        return None

    target_date = date.fromisoformat(target)
    return min(
        dates,
        key=lambda value: abs((date.fromisoformat(value) - target_date).days),
    )

def median_value(values):
    if not values:
        return None

    ordered = sorted(values)
    middle = len(ordered) // 2

    if len(ordered) % 2:
        return ordered[middle]

    return (ordered[middle - 1] + ordered[middle]) / 2

def merge_ranges(ranges):
    if not ranges:
        return None

    ordered = sorted(ranges, key=lambda interval: interval[0])
    merged = []

    for start, end in ordered:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return tuple(tuple(interval) for interval in merged)

def shortest_path(graph, start, goal):
    from collections import deque

    if start == goal:
        return (start,)

    parents = {start: None}
    queue = deque([start])

    while queue:
        node = queue.popleft()

        for neighbor in graph.get(node, ()):
            if neighbor in parents:
                continue

            parents[neighbor] = node

            if neighbor == goal:
                path = []
                current = goal
                while current is not None:
                    path.append(current)
                    current = parents[current]
                return tuple(reversed(path))

            queue.append(neighbor)

    return None

def topological_order(nodes, edges):
    nodes = tuple(nodes)
    node_set = set(nodes)
    outgoing = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}

    for source, destination in edges:
        if source not in node_set or destination not in node_set:
            raise ValueError("edge references an unknown node")
        outgoing[source].append(destination)
        indegree[destination] += 1

    ready = [node for node in nodes if indegree[node] == 0]
    order = []

    while ready:
        node = ready.pop(0)
        order.append(node)
        for destination in outgoing[node]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                ready.append(destination)

    if len(order) != len(nodes):
        raise ValueError("graph contains a cycle")

    return tuple(order)
